16	func scanRun(contextName string, targets ...string) jobs.Run {
17		return jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, contextName, "~/work", targets...)
18	}
19	
20	// jobsSeen returns every snapshot a view was handed, newest last.
21	func jobsSeen(v *fakeView) []jobs.ChangedMsg {
22		var out []jobs.ChangedMsg
23		for _, msg := range v.received {
24			if typed, ok := msg.(jobs.ChangedMsg); ok {
25				out = append(out, typed)
26			}
27		}
28		return out
29	}
30	
31	func lastJobs(t *testing.T, v *fakeView) jobs.ChangedMsg {
32		t.Helper()
33		seen := jobsSeen(v)
34		if len(seen) == 0 {
35			t.Fatal("the view was never handed a snapshot")
36		}
37		return seen[len(seen)-1]
38	}
39	
40	// D1: the snapshot goes to every view the router holds, whether or not it is on
41	// screen. A view is told where it stands, so coming back to it shows what
42	// happened while it was away without it having to ask.
43	func TestASnapshotReachesEveryHeldView(t *testing.T) {
44		dashboard := &fakeView{}
45		ws := &fakeView{}
46		sec := &fakeView{}
47		a := router(t, dashboard)
48		a.views[command.ViewWorkspaces] = ws
49		a.views[command.ViewSecurity] = sec
50	
51		a.jobs.Start(scanRun("default", "a", "b"))
52		a.jobsChanged()
53	
54		for name, view := range map[string]*fakeView{"dashboard": dashboard, "ws": ws, "security": sec} {
55			snapshot := lastJobs(t, view)
56			if got, want := len(snapshot.Runs), 1; got != want {
57				t.Errorf("%s was handed %d runs, want %d", name, got, want)
58			}
59			if got, want := snapshot.Running(), 1; got != want {
60				t.Errorf("%s sees %d running, want %d", name, got, want)
61			}
62		}
63		if a.currentView != command.ViewDashboard {
64			t.Errorf("broadcasting the snapshot switched the view to %s", a.currentView)
65		}
66	}
67	
68	// Rule 122: the frame in the message is bare, because a view puts it in a table
69	// cell, where it is measured before it is styled. A styled frame measures its
70	// escape sequence as width and is truncated inside it, which then bleeds down
71	// every row below.
72	func TestTheBroadcastFrameIsBareAndItsRenderingIsNot(t *testing.T) {
73		withTrueColor(t)
74	
75		view := &fakeView{}
76		a := router(t, view)
77		a.jobs.Start(scanRun("default", "a"))
78		a.jobsChanged()
79	
80		snapshot := lastJobs(t, view)
81	
82		if snapshot.Frame == "" {
83			t.Fatal("no spinner frame was carried")
84		}
85		if strings.Contains(snapshot.Frame, "\x1b") {
86			t.Errorf("Frame = %q carries an escape sequence; Rule 122 wants a cell measurable", snapshot.Frame)
87		}
88		if !strings.Contains(snapshot.RenderedFrame, "\x1b") {
89			t.Errorf("RenderedFrame = %q, want the styled frame a footer takes (Rule 128)", snapshot.RenderedFrame)
90		}
91		if !strings.Contains(snapshot.RenderedFrame, snapshot.Frame) {
92			t.Errorf("RenderedFrame = %q does not carry Frame = %q", snapshot.RenderedFrame, snapshot.Frame)
93		}
94	}
95	
96	// D5: one chain for the whole application. Asking twice while it is alive must
97	// not start a second, which is the failure the four hand-stamped spinners kept
98	// producing — two chains advancing one frame at twice the rate.
99	func TestOnlyOneSpinnerChainIsEverAlive(t *testing.T) {
100		a := router(t, &fakeView{})
101		a.jobs.Start(scanRun("default", "a"))
102	
103		first := a.ensureJobTick()
104		if first == nil {
105			t.Fatal("no chain was started for work that is running")
106		}
107		if second := a.ensureJobTick(); second != nil {
108			t.Error("a second chain was started while the first was alive")
109		}
110		if !a.jobTicking {
111			t.Error("the router does not know its chain is alive")
112		}
113	}
114	
115	// An empty registry animates nothing: a chain against no work would rebuild
116	// every view's rows ten times a second for a settled application.
117	func TestNoChainStartsWithNothingRunning(t *testing.T) {
118		a := router(t, &fakeView{})
119	
120		if cmd := a.ensureJobTick(); cmd != nil {
121			t.Error("a chain was started with an empty registry")
122		}
123	
124		// A settled run is not running work either.
