132	// The chain advances the frame and renews itself while work runs; it stops by
133	// not being renewed once nothing is left, and a later run starts a fresh one.
134	// That last half is what each view could not do: its chain died on the first
135	// idle tick and nothing brought it back, so the spinner froze on the frame it
136	// died at.
137	func TestTheChainRunsWhileWorkDoesAndRestartsAfterwards(t *testing.T) {
138		testutil.FastTimers(t, &jobSpinnerInterval)
139	
140		view := &fakeView{}
141		a := router(t, view)
